#include <math.h>
Float64 f(Float64 value,Float64 o,Float64 g);Float64 k(Float64 a,Float64 b,Float64 t);Str u(Int32 value);Int32 main(Void);Int32 w(Int32 limit);Float64 f(Float64 value,Float64 o,Float64 g){return fmax(o,fmin(value,g));}Float64 k(Float64 a,Float64 b,Float64 t){return(a+((b-a)*t));}Str u(Int32 value){if(((value%2)==0)){return "even";}else{return "odd";}}Int32 main(Void){Int32 i=0;while((i<2)){i=(i+1);}Int32 value=w(5);Str j=u(value);print("%s\n",j);return 0;}Int32 w(Int32 limit){Int32 aa=0;for(Int32 i=0;i<=limit;++i){aa=(aa+i);}return aa;}
